def transform(grid):
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            return [[2 if a != 0 and j < len(right[i]) and right[i][j] != 0 else 0 for j,a in enumerate(row)] for i,row in enumerate(left)]
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            top, bottom = grid[:r], grid[r+1:]
            return [[2 if a != 0 and bottom[i][j] != 0 else 0 for j,a in enumerate(row)] for i,row in enumerate(top)]
    return grid
